import * as THREE from 'three';
import { CSS3DObject, CSS3DRenderer } from 'three/addons/renderers/CSS3DRenderer.js';
import { loadExhibitionImage } from './exhibitionImage.js';

// The photograph and mount belong to the pavilion. Only its small audio label
// uses DOM rendering, sharing the same camera and physical plane.
export function createMuseumPortrait({ scene, host, element, box, plane, paper, edge, targets, invalidate, occluders, interactive = true }) {
  const group = new THREE.Group();
  group.position.set(22.325, 2.45, 3.4);
  group.rotation.y = -Math.PI / 2;
  scene.add(group);
  box(1.86, 2.8, .065, edge, 0, 0, 0, group);
  box(1.83, 2.77, .018, paper, 0, 0, .042, group);
  const photoMaterial = new THREE.MeshStandardMaterial({ color: '#e2dacc', roughness: 1 });
  const photograph = plane(1.62, 1.62 * 1404 / 1011, photoMaterial, 0, .13, .054, group);
  targets.push({ area: 'portrait', mesh: photograph });
  let disposed = false, texture;
  loadExhibitionImage('/assets/img/henry-rooftop-portrait.jpg', { maxDimension: 768 }).then(image => {
    if (disposed) return;
    texture = new THREE.Texture(image);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.needsUpdate = true;
    photoMaterial.map = texture;
    photoMaterial.color.set('#ffffff');
    photoMaterial.needsUpdate = true;
    invalidate();
  }).catch(() => {});

  const cssScene = new THREE.Scene();
  let cssRenderer, label;
  if (element) {
    cssRenderer = new CSS3DRenderer();
    Object.assign(cssRenderer.domElement.style, { position: 'absolute', inset: '0', pointerEvents: 'none' });
    host.appendChild(cssRenderer.domElement);
    label = new CSS3DObject(element);
    label.position.set(22.265, 1.245, 3.4);
    label.rotation.y = -Math.PI / 2;
    label.scale.setScalar(1.62 / 720);
    if (!interactive) element.style.pointerEvents = 'none';
    cssScene.add(label);
  }
  const bounds = new THREE.Box3().setFromObject(group);
  const probe = new THREE.Raycaster(), direction = new THREE.Vector3(), centre = new THREE.Vector3(22.265, 1.245, 3.4);
  return {
    group,
    resize(width, height) { cssRenderer?.setSize(width, height); },
    render(camera, area) {
      if (!cssRenderer) return;
      // DOM labels have no depth buffer. Check the actual masonry and objects
      // on the sightline, so this never appears through a wall or the globe.
      let visible = ['archive', 'portrait'].includes(area) && camera.position.x < 22 && camera.position.distanceTo(centre) < 14;
      if (visible) {
        direction.copy(centre).sub(camera.position);
        probe.set(camera.position, direction.clone().normalize());
        probe.far = direction.length() - .08;
        visible = !probe.intersectObjects(occluders, false).some(hit => hit.object !== photograph && hit.object.material?.visible !== false && !hit.object.userData.lettering && hit.distance > .05);
      }
      label.visible = visible;
      element.style.visibility = visible ? 'visible' : 'hidden';
      element.inert = !visible || !interactive;
      cssRenderer.render(cssScene, camera);
    },
    bounds,
    dispose() {
      disposed = true;
      texture?.dispose();
      // Vue retains ownership of the component's element and audio lifecycle.
      if (element) { element.style.visibility = 'hidden'; host.appendChild(element); }
      cssRenderer?.domElement.remove();
    },
  };
}
